import test from "node:test";
import assert from "node:assert/strict";
import zlib from "node:zlib";

import { crc32, readZip, validateEntryName, writeZip } from "../lib/zip.js";

test("crc32 matches known vectors", () => {
	assert.equal(crc32(Buffer.from("")), 0);
	assert.equal(crc32(Buffer.from("123456789")), 0xcbf43926);
	assert.equal(crc32(Buffer.from("hello")), 0x3610a686);
});

test("round-trips stored and deflated entries", () => {
	const small = "tiny";
	const large = "abc".repeat(5000);
	const archive = readZip(writeZip([
		{ name: "a.txt", data: small },
		{ name: "nested/b.txt", data: large },
		{ name: "bin/data.bin", data: Buffer.from([0, 1, 2, 255]) }
	]));
	assert.deepEqual(archive.names(), ["a.txt", "nested/b.txt", "bin/data.bin"]);
	assert.equal(archive.text("a.txt"), small);
	assert.equal(archive.text("nested/b.txt"), large);
	assert.deepEqual([...archive.read("bin/data.bin")], [0, 1, 2, 255]);
});

test("preserves UTF-8 names and text", () => {
	const archive = readZip(writeZip([{ name: "文档/说明.txt", data: "中文内容 😀" }]));
	assert.equal(archive.text("文档/说明.txt"), "中文内容 😀");
});

test("deflates when it wins, stores when it does not", () => {
	const archive = readZip(writeZip([
		{ name: "repeat.txt", data: "A".repeat(10000) },
		{ name: "random.bin", data: Buffer.from([0, 255, 0, 255]) }
	]));
	// Both read back identically; method choice is an implementation detail
	// that must never change the bytes.
	assert.equal(archive.text("repeat.txt").length, 10000);
	assert.deepEqual([...archive.read("random.bin")], [0, 255, 0, 255]);
});

test("rejects corrupt bodies by checksum", () => {
	const buffer = writeZip([{ name: "a.txt", data: "hello world hello world" }]);
	// Find the deflated payload after the 30-byte local header and 5-byte name.
	const nameLength = buffer.readUInt16LE(26);
	const start = 30 + nameLength;
	buffer[start + 2] ^= 0xff;
	assert.throws(() => readZip(buffer).text("a.txt"), (error) => error.code === "OFFICE_BAD_ZIP");
});

test("rejects traversal and absolute names", () => {
	for (const name of ["../evil", "/etc/passwd", "a/../../b", "C:\\evil", "a\0b"]) {
		assert.throws(() => validateEntryName(name), (error) => error.code === "OFFICE_BAD_ZIP", name);
	}
});

test("rejects non-zip input", () => {
	assert.throws(() => readZip(Buffer.from("not a zip at all, definitely not")), (error) => error.code === "OFFICE_BAD_ZIP");
});

test("archive reports missing entries without throwing", () => {
	const archive = readZip(writeZip([{ name: "a.txt", data: "x" }]));
	assert.equal(archive.has("b.txt"), false);
	assert.equal(archive.text("b.txt"), undefined);
});

test("a deflated entry round-trips through the system inflater", () => {
	// Proves the raw deflate stream we write is standard, not just readable by
	// our own reader (a shared bug would otherwise be invisible).
	const archive = readZip(writeZip([{ name: "a.txt", data: "hello hello hello" }]));
	const local = archive.buffer;
	const nameLength = local.readUInt16LE(26);
	const start = 30 + nameLength;
	const stored = local.subarray(start, start + local.readUInt32LE(18));
	if (local.readUInt16LE(8) === 8) {
		assert.equal(zlib.inflateRawSync(stored).toString("utf8"), "hello hello hello");
	}
});
